"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/skeleton.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type SkeletonProps = ComponentPropsWithRef<"div"> & {
  width?: number | string;
  height?: number | string;
  radius?: "small" | "medium" | "round";
};

export function Skeleton({ className, width, height, radius = "small", style, ...props }: SkeletonProps) {
  return <div className={cn("whatiuse-skeleton", `whatiuse-skeleton--${radius}`, className)} style={{ width, height, ...style }} aria-hidden="true" {...props} />;
}

export function SkeletonText({ lines = 3 }: { lines?: number }) {
  return <div className="whatiuse-skeleton-text" aria-hidden="true">{Array.from({ length: lines }, (_, index) => <Skeleton key={index} height={10} width={index === lines - 1 ? "68%" : "100%"} />)}</div>;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-skeleton { position: relative; overflow: hidden; border-radius: var(--whatiuse-radius-xs); background: var(--whatiuse-gray-100); }

.whatiuse-skeleton::after { position: absolute; inset: 0; background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.65), transparent); content: ""; transform: translateX(-100%); animation: whatiuse-skeleton-shimmer 1.6s linear infinite; }

.whatiuse-skeleton-text { display: grid; width: min(320px, 100%); gap: 8px; }

@media (prefers-reduced-motion: reduce) {
.whatiuse-skeleton::after { animation-duration: 2.4s; }
}

@keyframes whatiuse-skeleton-shimmer { to { transform: translateX(100%); } }
}
